CREATE TABLE IF NOT EXISTS app_users (mobile VARCHAR(10) PRIMARY KEY, mpin VARCHAR(4) NOT NULL, full_name VARCHAR(120), email VARCHAR(160));
CREATE TABLE IF NOT EXISTS vehicle_records (registration VARCHAR(20) PRIMARY KEY, owner_name VARCHAR(120), state_name VARCHAR(80), city VARCHAR(80), vehicle VARCHAR(100), fuel VARCHAR(30), status VARCHAR(50));
CREATE TABLE IF NOT EXISTS complaints (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, mobile VARCHAR(10), category VARCHAR(100), subcategory VARCHAR(100), vehicle VARCHAR(20), remarks VARCHAR(1000), created_at VARCHAR(40));
CREATE TABLE IF NOT EXISTS transactions (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, mobile VARCHAR(10), type VARCHAR(100), transaction_value VARCHAR(200), created_at VARCHAR(40));

CREATE TABLE IF NOT EXISTS licence_records (licence_number VARCHAR(30) PRIMARY KEY, owner_name VARCHAR(120), state_name VARCHAR(80), status VARCHAR(50));
